document.querySelectorAll('a[href^="#"]').forEach(link=>{link.addEventListener('click',e=>{const href=link.getAttribute('href');if(href==='#')return;e.preventDefault();const t=document.querySelector(href);if(t){window.scrollTo({top:t.getBoundingClientRect().top+window.scrollY-72,behavior:'smooth'})}})});
